INSERT INTO public.products (id, name, category, label, description, overview, features, url, keywords, coming_soon, image_url, image_alt, sort_order, created_at, updated_at, version, whats_new, label_en, description_en, overview_en, features_en, image_alt_en, whats_new_en, github_url, publication_date, beneficiary_details) VALUES ('radar', 'Tech Radar', 'technology', 'تقييم التقنيات', 'تقييم التقنيات وتصنيفها: تبنٍّ، تجربة، تقييم، إيقاف.', 'Tech Radar يحوّل قرارات التقنية إلى ممارسة دورية: كل تقنية في مكان واضح على الرادار، مع سببها وتاريخها، فتتكرّر المراجعة في جلسة واحدة.', '{"رادار بأربع حلقات: تبنٍّ، تجربة، تقييم، إيقاف","بطاقة لكل تقنية مع السبب والتاريخ","مراجعة دورية في جلسة واحدة","تتبّع التغيّرات بين المراجعات","توصيات مرتبطة بحالة التقنية","تصدير الرادار للعروض"}', 'https://radar.e20e.tools/', 'رادار تقييم تبني تجربة تصنيف radar assessment', 'f', 'products/radar.jpg', 'صورة Tech Radar', '30', '2026-10-13 16:50:31.747109+00', '2026-10-13 20:54:55.783+00', '', '', 'Technology Assessment', 'Assess and classify technologies: adopt, trial, assess, hold.', 'Tech Radar turns technology decisions into a recurring practice: every technology sits in a clear place on the radar, with its reason and date, so the review repeats in a single session.', '{"Radar with four rings: adopt, trial, assess, hold","A card for every technology with its reason and date","A recurring review in one session","Track changes between reviews","Recommendations tied to each technology status","Export the radar for presentations"}', 'Tech Radar product image', '', 'https://github.com/e20etools/', NULL, '{"goals": ["technology", "governance", "innovation"], "notFor": {"ar": "الجهات الصغيرة ذات تقنيات قليلة ثابتة، أو من يبحث عن أداة لإدارة المشاريع أو الأصول.", "en": "Small organisations with a few stable technologies, or teams looking for project or asset management."}, "audience": {"ar": "مكاتب البنية المؤسسية وفرق الهندسة ولجان التقنية التي تحتاج قرارًا موحدًا حول التقنيات التي تتبناها أو تجربها أو توقفها.", "en": "EA offices, engineering teams and technology boards that need one shared decision on which technologies to adopt, trial, assess or hold."}, "limitations": {"ar": ["قيمة الرادار تعتمد على تحديثه دوريًا", "لا يقيس الأداء الفني للتقنيات آليًا"], "en": ["Its value depends on regular reviews", "Does not measure technical performance automatically"]}, "integrations": {"ar": ["تصدير واستيراد Excel/CSV", "ربط بمشهد التطبيقات (APM)", "مشاركة الرادار عبر رابط"], "en": ["Excel/CSV import and export", "Link to the application landscape (APM)", "Share the radar via link"]}, "exampleOutput": {"ar": "رادار مرئي بأربع حلقات (تبنَّ، جرّب، قيّم، أوقف) لكل مجال، مع مبرر كل قرار وتاريخ مراجعته.", "en": "A visual four-ring radar (Adopt, Trial, Assess, Hold) per quadrant, with the rationale and review date for every decision."}, "prerequisites": {"ar": ["قائمة أولية بالتقنيات المستخدمة", "لجنة أو مالك يعتمد التصنيفات", "معايير تقييم متفق عليها"], "en": ["An initial list of technologies in use", "A board or owner who approves ratings", "Agreed assessment criteria"]}, "maturityLevels": ["developing", "established"], "organizationSizes": ["medium", "large", "enterprise"]}');
INSERT INTO public.products (id, name, category, label, description, overview, features, url, keywords, coming_soon, image_url, image_alt, sort_order, created_at, updated_at, version, whats_new, label_en, description_en, overview_en, features_en, image_alt_en, whats_new_en, github_url, publication_date, beneficiary_details) VALUES ('platform', 'EA Tool', 'platform', 'منصة متكاملة', 'منصة E20E المتكاملة لإدارة البنية المؤسسية.', 'EA Tool تجمع نموذج المؤسسة وخريطة التقنيات والرادار في منصة واحدة: تبدأ من صورة واحدة وتنتهي بقرار موثّق. الإطلاق قريبًا.', '{"نموذج المؤسسة وخريطة التقنيات في مكان واحد","رادار التقنيات موصول بخريطة التطبيقات","تقارير موحّدة لأصحاب القرار","صلاحيات لعدة إدارات","سجل قرارات وتاريخ مراجعات","تكامل مع أدوات التصميم والإدارة"}', 'https://platform.e20e.tools/', 'منصة إدارة معمارية enterprise platform e20e البنية المؤسسية', 't', 'products/platform.jpg', 'صورة EA Tool', '40', '2026-10-13 16:50:31.747109+00', '2026-10-13 16:50:31.747109+00', '', '', 'Integrated Platform', 'The integrated E20E platform for managing enterprise architecture.', 'EA Tool brings the enterprise model, technology landscape and radar into one platform: start from a single picture and end with a documented decision. Launching soon.', '{"Enterprise model and technology landscape in one place","Technology radar linked to the application map","Unified reports for decision makers","Permissions for multiple departments","Decision log and review history","Integration with design and management tools"}', 'EA Tool product image', '', 'https://github.com/e20etools/', NULL, '{"goals": ["architecture", "applications", "technology", "governance"], "notFor": {"ar": "من يحتاج أداة واحدة محددة فقط، أو جهة بلا فريق مسؤول عن البنية المؤسسية.", "en": "Teams needing only one specific tool, or organisations without anyone owning enterprise architecture."}, "audience": {"ar": "الجهات التي تريد إدارة البنية المؤسسية كاملة في مكان واحد: القدرات والتطبيقات والتقنيات والتكاليف والحوكمة.", "en": "Organisations that want to run their whole enterprise architecture in one place: capabilities, applications, technology, cost and governance."}, "limitations": {"ar": ["يتطلب وقتًا لتجهيز البيانات قبل ظهور القيمة الكاملة", "يحتاج حوكمة لتحديث البيانات باستمرار"], "en": ["Needs time to prepare data before full value appears", "Requires governance to keep data current"]}, "integrations": {"ar": ["استيراد Excel/CSV", "تسجيل دخول موحد (SSO) حسب الإعداد", "واجهات برمجية للربط مع CMDB والأنظمة المالية"], "en": ["Excel/CSV import", "Single sign-on (SSO) as configured", "APIs to connect CMDB and finance systems"]}, "exampleOutput": {"ar": "لوحة موحدة تربط القدرات بالتطبيقات والتقنيات وتكاليفها، مع تقارير جاهزة للإدارة العليا.", "en": "One dashboard linking capabilities to applications, technologies and their costs, with executive-ready reports."}, "prerequisites": {"ar": ["راعٍ تنفيذي وفريق بنية مؤسسية", "بيانات أولية عن التطبيقات والقدرات", "خطة تبنٍّ على مراحل"], "en": ["An executive sponsor and an EA team", "Initial application and capability data", "A phased adoption plan"]}, "maturityLevels": ["developing", "established"], "organizationSizes": ["medium", "large", "enterprise"]}');
INSERT INTO public.products (id, name, category, label, description, overview, features, url, keywords, coming_soon, image_url, image_alt, sort_order, created_at, updated_at, version, whats_new, label_en, description_en, overview_en, features_en, image_alt_en, whats_new_en, github_url, publication_date, beneficiary_details) VALUES ('innovation', 'Innovation', 'technology', 'إدارة الابتكار', 'جمع الأفكار وتقييمها ومتابعة تحويلها إلى مبادرات.', 'Innovation يحوّل الأفكار المتفرقة إلى مسار واحد: تُجمع الأفكار من كل الإدارات، وتُقيَّم بمعايير واحدة، ثم تُتابع مبادراتها من الفكرة حتى التشغيل مع أثرها المقاس.', '{"صندوق أفكار موحّد لكل الإدارات","تقييم الأفكار بمعايير الأثر والجهد والجدوى","جلسات مراجعة بتعليقات وقرارات موثّقة","تحويل الأفكار المقبولة إلى مبادرات متابعة","قياس الأثر بعد التشغيل","لوحة حالة للبرامج والمبادرات الجارية"}', '', 'أفكار مبادرات ابتكار تقييم أثر ideas innovation', 't', 'products/innovation.jpg', 'تصور توضيحي لمسار الأفكار من الجمع إلى التقييم في Innovation', '100', '2026-10-13 20:11:42.993205+00', '2026-10-13 20:11:42.964+00', '1.0', '', 'Innovation Management', 'Collect and assess ideas, and follow them through into initiatives.', 'Innovation turns scattered ideas into a single track: ideas are collected from every department, assessed against one set of criteria, then their initiatives are followed from idea to live service with measured impact.', '{"One idea box for every department","Score ideas on impact, effort and feasibility","Review sessions with comments and documented decisions","Turn accepted ideas into initiatives","Track measured impact after go-live","Status board for running programmes and initiatives"}', 'Illustration of the idea flow from collection to assessment in Innovation', '', 'https://github.com/e20etools/', NULL, '{"goals": ["innovation", "governance"], "notFor": {"ar": "من يحتاج نظامًا لإدارة المشاريع التفصيلية أو الميزانيات بعد بدء التنفيذ.", "en": "Teams needing detailed project or budget management once delivery starts."}, "audience": {"ar": "مكاتب الابتكار والتحول الرقمي التي تجمع أفكار الموظفين وتقيّمها وتحوّل الأفضل منها إلى مبادرات.", "en": "Innovation and digital transformation offices that collect staff ideas, assess them and turn the best into initiatives."}, "limitations": {"ar": ["لا يدير تنفيذ المشاريع بعد اعتمادها", "جودة النتائج تعتمد على مشاركة الموظفين"], "en": ["Does not manage project delivery after approval", "Results depend on staff participation"]}, "integrations": {"ar": ["تصدير Excel/CSV", "ربط المبادرات بالقدرات في البنية المؤسسية", "إشعارات البريد حسب الإعداد"], "en": ["Excel/CSV export", "Link initiatives to EA capabilities", "Email notifications as configured"]}, "exampleOutput": {"ar": "قمع ابتكار يعرض الأفكار حسب المرحلة ودرجة التقييم، وقائمة بالمبادرات المعتمدة ومالكيها.", "en": "An innovation funnel showing ideas by stage and score, plus a list of approved initiatives and their owners."}, "prerequisites": {"ar": ["معايير تقييم واضحة للأفكار", "لجنة أو مقيّمين معتمدين", "تحديد مسار تحويل الفكرة إلى مبادرة"], "en": ["Clear idea assessment criteria", "A panel or approved reviewers", "A defined path from idea to initiative"]}, "maturityLevels": ["starting", "developing", "established"], "organizationSizes": ["medium", "large", "enterprise"]}');
INSERT INTO public.products (id, name, category, label, description, overview, features, url, keywords, coming_soon, image_url, image_alt, sort_order, created_at, updated_at, version, whats_new, label_en, description_en, overview_en, features_en, image_alt_en, whats_new_en, github_url, publication_date, beneficiary_details) VALUES ('landscape', 'APM & App Landscape', 'technology', 'خريطة التقنيات', 'استكشاف خريطة التقنيات والتطبيقات والعلاقات بينها.', 'Landscape يرسم صورة حيّة للتطبيقات والعلاقات بينها، فتعرف فورًا ما يعمل، وما يتكرر، وما يقترب من نهاية عمره، ومن يملك كل جزء.', '{"خريطة تفاعلية للتطبيقات وعلاقاتها","تصنيف حسب المجال والإدارة والحالة","كشف التكرار والتداخل بين الأنظمة","مسار البيانات بين الأنظمة","بحث وتصفية سريعة حسب الطبقة","تصدير الخريطة للاجتماعات والقرارات"}', 'https://apm.e20e.tools', 'خريطة تطبيقات علاقات استكشاف technology map applications', 'f', 'products/landscape.jpg', 'صورة Landscape', '20', '2026-10-13 16:50:31.747109+00', '2026-10-13 20:56:24.217+00', '', '', 'Technology Landscape', 'Explore your technology landscape, applications and the relationships between them.', 'Landscape draws a live picture of your applications and how they relate, so you instantly see what is running, what is duplicated, what is nearing end of life, and who owns each part.', '{"Interactive map of applications and their relationships","Classify by domain, department and status","Spot duplication and overlap between systems","Data flow between systems","Fast search and filtering by layer","Export the map for meetings and decisions"}', 'Landscape product image', '', 'https://github.com/e20etools/', NULL, '{"goals": ["applications", "architecture", "cost"], "notFor": {"ar": "من يحتاج مراقبة تشغيلية لحظية للخوادم والشبكات (أدوات المراقبة أنسب).", "en": "Teams needing real-time operational monitoring of servers and networks (monitoring tools fit better)."}, "audience": {"ar": "مكاتب البنية المؤسسية وإدارات تقنية المعلومات التي تحتاج حصرًا كاملًا للتطبيقات وعلاقاتها لاتخاذ قرارات الترشيد.", "en": "EA offices and IT departments that need a full inventory of applications and their relationships to make rationalisation decisions."}, "limitations": {"ar": ["لا يكتشف التطبيقات آليًا من الشبكة", "دقة الخريطة تعتمد على تحديث المالكين"], "en": ["Does not auto-discover applications from the network", "Map accuracy depends on owners updating it"]}, "integrations": {"ar": ["استيراد Excel/CSV", "ربط برادار التقنية وإدارة التكاليف (ITFM)", "واجهات برمجية مع CMDB"], "en": ["Excel/CSV import", "Link to the Tech Radar and cost management (ITFM)", "APIs with CMDB"]}, "exampleOutput": {"ar": "خريطة مشهد التطبيقات مع العلاقات والتكاملات، وتقييم TIME (احتفظ، استثمر، انقل، أزِل) لكل تطبيق.", "en": "An application landscape map with relationships and integrations, and a TIME rating (Tolerate, Invest, Migrate, Eliminate) per application."}, "prerequisites": {"ar": ["قائمة التطبيقات الحالية ومالكيها", "تعريف القدرات أو الخدمات المدعومة", "مسؤول عن تحديث البيانات"], "en": ["Current application list and owners", "Defined capabilities or supported services", "An owner for keeping data current"]}, "maturityLevels": ["starting", "developing", "established"], "organizationSizes": ["medium", "large", "enterprise"]}');
INSERT INTO public.products (id, name, category, label, description, overview, features, url, keywords, coming_soon, image_url, image_alt, sort_order, created_at, updated_at, version, whats_new, label_en, description_en, overview_en, features_en, image_alt_en, whats_new_en, github_url, publication_date, beneficiary_details) VALUES ('itfm', 'ITFM', 'technology', 'إدارة تكاليف التقنية', 'تتبّع تكاليف التقنية وربطها بالخدمات والقرارات.', 'ITFM يوضّح أين تُصرف ميزانية التقنية: تكلفة كل خدمة وتطبيق ومورد، وتوزيعها على الإدارات، فتُبنى قرارات الترشيد والتطوير على أرقام واضحة بدل تقديرات عامة.', '{"تجميع تكاليف البنية والسحابة والتراخيص في مكان واحد","توزيع التكلفة على الإدارات والخدمات","ربط كل تكلفة بالتطبيق أو الخدمة التي أنتجتها","تتبّع الالتزامات التعاقدية والتجديدات القادمة","تحليل الانحراف بين الميزانية المعتمدة والصرف الفعلي","تقارير تكلفة جاهزة للإدارة وللمالية"}', '', 'تكاليف ميزانية تقنية مالية ترشيد cost financial budget itfm', 't', 'products/itfm.jpg', 'تصور توضيحي لتوزيع تكاليف التقنية على الخدمات في ITFM', '100', '2026-10-13 20:10:58.463226+00', '2026-10-13 20:10:58.416+00', '1.0', '', 'Technology Cost Management', 'Track technology costs and link them to services and decisions.', 'ITFM shows where the technology budget is spent: the cost of every service, application and resource, and how it is spread across departments, so rationalisation and investment decisions rest on clear numbers instead of rough estimates.', '{"Gather infrastructure, cloud and licence costs in one place","Allocate cost across departments and services","Link every cost to the application or service it produced","Track contractual commitments and upcoming renewals","Analyse variance between approved budget and actual spend","Cost reports ready for management and finance"}', 'Illustration of technology cost allocation across services in ITFM', '', 'https://github.com/e20etools/', NULL, '{"goals": ["cost", "governance", "technology"], "notFor": {"ar": "من يحتاج نظامًا محاسبيًا أو لإصدار الفواتير والمدفوعات.", "en": "Teams needing an accounting, invoicing or payments system."}, "audience": {"ar": "إدارات تقنية المعلومات والمالية التي تريد معرفة تكلفة كل خدمة وتطبيق وربط الإنفاق بالقرارات.", "en": "IT and finance teams that want to know the cost of each service and application and link spending to decisions."}, "limitations": {"ar": ["لا يستبدل النظام المحاسبي (ERP)", "دقة التكاليف تعتمد على جودة البيانات المدخلة"], "en": ["Does not replace the accounting system (ERP)", "Cost accuracy depends on input data quality"]}, "integrations": {"ar": ["استيراد Excel/CSV", "ربط بمشهد التطبيقات (APM)", "تصدير تقارير للأنظمة المالية"], "en": ["Excel/CSV import", "Link to the application landscape (APM)", "Report export to finance systems"]}, "exampleOutput": {"ar": "تقرير تكلفة لكل خدمة وتطبيق، مع اتجاه الإنفاق وفرص الترشيد والتراخيص غير المستخدمة.", "en": "A cost report per service and application, with spending trends, savings opportunities and unused licences."}, "prerequisites": {"ar": ["بيانات الإنفاق والعقود والتراخيص", "قائمة الخدمات أو التطبيقات", "نموذج توزيع تكاليف متفق عليه مع المالية"], "en": ["Spend, contract and licence data", "A list of services or applications", "A cost allocation model agreed with finance"]}, "maturityLevels": ["developing", "established"], "organizationSizes": ["medium", "large", "enterprise"]}');
INSERT INTO public.products (id, name, category, label, description, overview, features, url, keywords, coming_soon, image_url, image_alt, sort_order, created_at, updated_at, version, whats_new, label_en, description_en, overview_en, features_en, image_alt_en, whats_new_en, github_url, publication_date, beneficiary_details) VALUES ('archone', 'ArchONE', 'architecture', 'البنية المؤسسية', 'نمذجة البنية المؤسسية وتوثيق القدرات والعمليات.', 'ArchONE يبني مع فريقك نموذجًا واضحًا للمؤسسة: القدرات، العمليات، التطبيقات وعلاقاتها في مساحة واحدة، فتنتهي الاجتماعات بقرار موثّق بدل نقاش عام.', '{"نمذجة القدرات والعمليات في طبقات واضحة","ربط كل تطبيق بالقدرات والعمليات التي يخدمها","كشف الفجوات والتكرار بين الإدارات","لوحات جاهزة للعرض على الإدارة","تصدير النماذج صورًا ومراجعات","سجل تعديلات يوضّح من غيّر وماذا"}', 'https://archone.e20e.tools/', 'نمذجة قدرات عمليات توثيق architecture modeling البنية المؤسسية', 't', 'products/archone.jpg', 'صورة ArchONE', '10', '2026-10-13 16:50:31.747109+00', '2026-11-16 22:28:09.864119+00', '1.0', '', 'Enterprise Architecture', 'Model and document your enterprise architecture, capabilities and processes.', 'ArchONE builds a clear model of your enterprise with your team: capabilities, processes, applications and the relationships between them in one space, so meetings end with a documented decision instead of open discussion.', '{"Capability and process modelling in clear layers","Link every application to the capabilities and processes it serves","Detect gaps and duplication across departments","Board-ready dashboards for management","Export models as images and reviews","Change log showing who changed what"}', '', '', 'https://github.com/e20etools/', '2026-12-01', '{"goals": ["architecture", "governance", "applications"], "notFor": {"ar": "من يحتاج أداة رسم عامة فقط، أو أتمتة تشغيل العمليات (BPM).", "en": "Teams needing only a general drawing tool, or process execution automation (BPM)."}, "audience": {"ar": "معماريو المؤسسة ومكاتب البنية المؤسسية الذين ينمذجون القدرات والعمليات والتطبيقات ويوثّقونها وفق أطر مثل TOGAF.", "en": "Enterprise architects and EA offices who model and document capabilities, processes and applications using frameworks such as TOGAF."}, "limitations": {"ar": ["قيد الإطلاق؛ بعض الميزات تُتاح تدريجيًا", "يحتاج معرفة أساسية بالبنية المؤسسية"], "en": ["Launching; some features roll out gradually", "Needs basic enterprise-architecture knowledge"]}, "integrations": {"ar": ["استيراد وتصدير Excel/CSV", "ربط بمشهد التطبيقات ورادار التقنية", "تصدير المخططات والتقارير"], "en": ["Excel/CSV import and export", "Link to the application landscape and Tech Radar", "Export diagrams and reports"]}, "exampleOutput": {"ar": "خريطة قدرات مؤسسية متعددة المستويات مربوطة بالعمليات والتطبيقات، مع تقييم نضج لكل قدرة.", "en": "A multi-level business capability map linked to processes and applications, with a maturity rating per capability."}, "prerequisites": {"ar": ["إطار أو منهجية بنية مؤسسية معتمدة", "خريطة قدرات أولية", "فريق مسؤول عن النماذج"], "en": ["An adopted EA framework or method", "An initial capability map", "A team owning the models"]}, "maturityLevels": ["starting", "developing", "established"], "organizationSizes": ["medium", "large", "enterprise"]}');
INSERT INTO public.site_settings (id, display_title, arabic_title, description, logo_url, heading_font, body_font, colors, updated_at, categories, footer_text, description_en, categories_en, display_title_en, footer_text_en, navigation_items, tagline, tagline_en, nav_style, motion_enabled, motion_speed, motion_direction, image_fit, image_brightness, image_contrast, image_saturation, image_sharpen, mobile_nav_style, feature_flags, contact_info, design_theme, footer_links, theme_customizations, terms_content, archy_greeting) VALUES ('t', 'E20E Tools', '', 'EA Tools Build by EA to EA.', 'branding/07233eca-fed8-40d5-9c19-0fefad5fdf85.png', 'Alexandria', 'Alexandria', '{"--primary": "oklch(20.5% .009 48)"}', '2026-11-13 17:50:35.286+00', '{"platform": "Innovation", "technology": "إدارة التقنيات", "architecture": "البنية المؤسسية"}', 'Build with ♥ By TAQNIA.ME & DT.Guide', 'EA Tools Build by EA to EA.', '{"platform": "Integrated Platforms", "technology": "Technology Management", "architecture": "Enterprise Architecture"}', 'E20E Tools', 'Build with ♥ By TAQNIA.ME & DT.Guide', '[{"id": "77e94a3c-5189-4536-9eda-022a8790baf5", "cta": false, "url": "/", "labelAr": "الرئيسية", "labelEn": "Home"}, {"id": "roadmap", "cta": false, "url": "/technology-roadmap", "labelAr": "الخارطة", "labelEn": "Roadmap"}, {"id": "consultations", "cta": false, "url": "https://www.dt.guide/itconsultations/", "labelAr": "الاستشارات", "labelEn": "Consultations"}, {"id": "courses", "cta": false, "url": "https://www.dt.guide/courses/", "labelAr": "الدورات", "labelEn": "Courses"}, {"id": "support", "cta": false, "url": "/support", "hidden": true, "labelAr": "ادعمنا", "labelEn": "Support us"}, {"id": "request", "cta": false, "url": "/request", "labelAr": "اطلب", "labelEn": "Request"}, {"id": "about", "cta": false, "url": "/about", "hidden": false, "labelAr": "من نحن", "labelEn": "About us"}, {"id": "6158212a-0fa3-4e6c-a5f6-72366ff4ec6b", "cta": false, "url": "/affiliates", "hidden": true, "labelAr": "التو